    # For n == 1, sequences are just single elements from 1 to max_element
    if n == 1:
        return max_element

    # dp[x]: number of sequences of length 'current length' ending with element x
    dp = [0] * (max_element + 1)
    for x in range(1, max_element + 1):
        dp[x] = 1  # sequences of length 1 ending with x

    for length in range(2, n + 1):
        new_dp = [0] * (max_element + 1)
        # prefix sums for dp to speed up summation
        prefix = [0] * (max_element + 2)
