def find_solution(a, b, n):
    # We want non-negative integers x, y such that a*x + b*y = n.
    # If a or b is zero, handle separately.
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Extended Euclidean algorithm to find one particular solution
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # a and b divided by gcd
    a_div = a // g
    b_div = b // g

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    #
    # We want x >= 0 and y >= 0
    # => x0 + k*b_div >= 0  => k >= -x0 / b_div
    # => y0 - k*a_div >= 0  => k <= y0 / a_div

    # Find range of k that satisfies both inequalities
    import math

    k_min = math.ceil(-x0 / b_div) if b_div != 0 else float('-inf')
    k_max = math.floor(y0 / a_div) if a_div != 0 else float('inf')

    if k_min > k_max:
        return None

    # Any k in [k_min, k_max] works; choose k = k_min to get smallest x
    k = k_min

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return None

    return (x, y)

