def dict_depth(d):
    if not isinstance(d, dict):
        return 0

    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            depth = 1 + dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            # Check for dicts inside list/tuple to find nested dict depth,
            # but do not add depth for the list/tuple itself.
            def max_nested_dict_depth(obj):
                max_d = 0
                if isinstance(obj, dict):
                    max_d = dict_depth(obj)
                elif isinstance(obj, (list, tuple)):
                    for item in obj:
                        d_ = max_nested_dict_depth(item)
                        if d_ > max_d:
                            max_d = d_
                return max_d

            depth = 1 + max_nested_dict_depth(v)
            if depth > max_depth:
                max_depth = depth

    return max_depth

